-- Why: manual schema rollback of 0017_notification_core (R14 §3.2, L3); idempotent, no table depends on the other.
-- WARNING: destroys every Inbox card and notification preference. Cards are derived from task/project history,
-- so they can be regenerated by future events, but what users had not read yet is gone. Take a backup first (R14 L2).
-- Dropping a table also drops its indexes, CHECKs and foreign keys, so none are listed separately.
-- After running this, remove the journal row so db:migrate can re-apply 0017:
--   DELETE FROM drizzle.__drizzle_migrations WHERE created_at = 1792270058258;
DROP TABLE IF EXISTS "notification_pref";
DROP TABLE IF EXISTS "notification";
